import React, { useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { useGLTF } from '@react-three/drei';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import * as THREE from 'three';

gsap.registerPlugin(ScrollTrigger);

interface BurgerModelProps {
  containerRef: React.RefObject<HTMLDivElement | null>;
}

function BurgerModel({ containerRef }: BurgerModelProps) {
  const groupRef = useRef<THREE.Group>(null);
  const topBunRef = useRef<THREE.Mesh>(null);
  const pattyRef = useRef<THREE.Mesh>(null);
  const bottomBunRef = useRef<THREE.Mesh>(null);

  const { nodes, materials } = useGLTF('/models/burger.glb') as any;

  useGSAP(
    () => {
      if (!groupRef.current || !containerRef.current) return;

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 1,
        },
      });

      // Rotate the entire product during scroll
      tl.to(groupRef.current.rotation, { y: Math.PI * 2, ease: 'none' }, 0);

      // Explode layers vertically at specific scroll markers
      if (topBunRef.current) {
        tl.to(topBunRef.current.position, { y: 2.2, ease: 'power1.out' }, 0.2);
      }
      if (pattyRef.current) {
        tl.to(pattyRef.current.position, { y: 0.5, ease: 'power1.out' }, 0.3);
      }
      if (bottomBunRef.current) {
        tl.to(bottomBunRef.current.position, { y: -1.2, ease: 'power1.out' }, 0.2);
      }
    },
    { scope: containerRef }
  );

  return (
    <group ref={groupRef} dispose={null}>
      <mesh ref={topBunRef} geometry={nodes.TopBun.geometry} material={materials.Bun} />
      <mesh ref={pattyRef} geometry={nodes.Patty.geometry} material={materials.Meat} />
      <mesh ref={bottomBunRef} geometry={nodes.BottomBun.geometry} material={materials.Bun} />
    </group>
  );
}

export default function ProductShowcase() {
  const containerRef = useRef<HTMLDivElement>(null);

  return (
    <div ref={containerRef} className="relative h-[300vh] bg-stone-900">
      <div className="sticky top-0 h-screen w-full">
        <Canvas
          dpr={[1, 2]}
          camera={{ position: [0, 0, 5], fov: 45 }}
          gl={{ antialias: true, powerPreference: 'high-performance' }}
        >
          <ambientLight intensity={0.7} />
          <directionalLight position={[10, 10, 5]} intensity={1.2} />
          <BurgerModel containerRef={containerRef} />
        </Canvas>
      </div>
    </div>
  );
}
